/// <summary>
/// Creates new record in AVACustInvoiceLineAdjust table and modifies related tables.
/// </summary>
/// <param name="sender">AddInvoiceLineAdjust form button</param>
/// <param name="e">Clicked event</param>
[FormControlEventHandler(formControlStr(CustFreeInvoice, AddInvoiceLineAdjust), FormControlEventType::Clicked)]
public static void AddInvoiceLineAdjust_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormDataSource avaCustInvoiceLineAdjust_ds = sender.formRun().dataSource('AVACustInvoiceLineAdjust');
    AVACustInvoiceLineAdjust avaCustInvoiceLineAdjust = avaCustInvoiceLineAdjust_ds.cursor();

    FormDataSource custInvoiceLine_ds = sender.formRun().dataSource('CustInvoiceLine');
    CustInvoiceLine custInvoiceLine = custInvoiceLine_ds.cursor();

    FormDataSource custInvoiceTable_ds = sender.formRun().dataSource('CustInvoiceTable');
    CustInvoiceTable custInvoiceTable = custInvoiceTable_ds.cursor();

    avaCustInvoiceLineAdjust.initFromCustInvoiceLine(custInvoiceLine);
    avaCustInvoiceLineAdjust.insert();

    if(!custInvoiceLine.AVAHasAdjustment)
    {
        custInvoiceLine.AVAHasAdjustment = NoYes::Yes;
    }

    if(!custInvoiceTable.AVAHasAdjustment)
    {
        custInvoiceTable.AVAHasAdjustment = NoYes::Yes;
    }

    avaCustInvoiceLineAdjust_ds.refresh();
    avaCustInvoiceLineAdjust_ds.research(true);
}

/// <summary>
/// Deletes record from AVACustInvoiceLineAdjust table and modifies related tables.
/// </summary>
/// <param name="sender">AVACustInvoiceLineAdjust datasource</param>
/// <param name="e">Deleted event</param>
[FormDataSourceEventHandler(formDataSourceStr(CustFreeInvoice, AVACustInvoiceLineAdjust), FormDataSourceEventType::Deleted)]
public static void AVACustInvoiceLineAdjust_OnDeleted(FormDataSource sender, FormDataSourceEventArgs e)
{
    if(!sender.getNext())
    {
        FormDataSource custInvoiceLine_ds = sender.formRun().dataSource('CustInvoiceLine');
        CustInvoiceLine custInvoiceLine = custInvoiceLine_ds.cursor();

        FormDataSource custInvoiceTable_ds = sender.formRun().dataSource('CustInvoiceTable');
        CustInvoiceTable custInvoiceTable = custInvoiceTable_ds.cursor();

        if(custInvoiceLine.AVAHasAdjustment)
        {
            custInvoiceLine.AVAHasAdjustment = NoYes::No;
        }

        if(custInvoiceTable.AVAHasAdjustment)
        {
            custInvoiceTable.AVAHasAdjustment = NoYes::No;
        }

        sender.refresh();
        sender.research(true);
    }
}
